import{_ as e,o as i,c as l,a3 as o}from"./chunks/framework.DXf0zkj5.js";const m=JSON.parse('{"title":"Architecture Decisions Confirmation List [CONFIRM WITH DEVELOPER]","description":"","frontmatter":{},"headers":[],"relativePath":"12-confirm-list.md","filePath":"12-confirm-list.md"}'),s={name:"12-confirm-list.md"};function n(r,t,a,d,c,g){return i(),l("div",null,[...t[0]||(t[0]=[o('<h1 id="architecture-decisions-confirmation-list-confirm-with-developer" tabindex="-1">Architecture Decisions Confirmation List [CONFIRM WITH DEVELOPER] <a class="header-anchor" href="#architecture-decisions-confirmation-list-confirm-with-developer" aria-label="Permalink to &quot;Architecture Decisions Confirmation List [CONFIRM WITH DEVELOPER]&quot;">​</a></h1><p>The following design decisions and operational assumptions were deduced from the codebase and should be confirmed by the primary engineer:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Item #</th><th style="text-align:left;">Topic</th><th style="text-align:left;">Deduced Design Choice</th><th style="text-align:left;">Location in Codebase</th><th style="text-align:left;">Rationale to Confirm</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>C1</strong></td><td style="text-align:left;">Storage Tiering</td><td style="text-align:left;">Defaulting to in-memory <code>MemoryStore</code> with flat segment <code>DiskStore</code> fallback instead of Redis.</td><td style="text-align:left;"><code>src/cache/store.ts</code></td><td style="text-align:left;">Selected to achieve true sub-millisecond lookups (&lt; 0.1ms) without external network hops.</td></tr><tr><td style="text-align:left;"><strong>C2</strong></td><td style="text-align:left;">Coalescing Policy</td><td style="text-align:left;">In-flight leader-follower stream fanout instead of queuing in Redis/RabbitMQ.</td><td style="text-align:left;"><code>src/proxy/coalesce.ts</code></td><td style="text-align:left;">Eliminates distributed locking overhead; maximizes local proxy throughput.</td></tr><tr><td style="text-align:left;"><strong>C3</strong></td><td style="text-align:left;">Purge Strategy</td><td style="text-align:left;">Synchronous purge for &lt; 50 items; asynchronous worker queue for &gt; 50 items.</td><td style="text-align:left;"><code>src/purge/api.ts:25</code></td><td style="text-align:left;">Prevents event loop blocking during massive tenant or tag purge operations.</td></tr><tr><td style="text-align:left;"><strong>C4</strong></td><td style="text-align:left;">AIML Tier Role</td><td style="text-align:left;">Tier A/B models strictly advisory; zero AI models placed on critical latency path.</td><td style="text-align:left;"><code>aiml/MODEL_CARD.md</code></td><td style="text-align:left;">Ensures strict deterministic RFC 9111 correctness and avoids latency jitter.</td></tr><tr><td style="text-align:left;"><strong>C5</strong></td><td style="text-align:left;">Compression Cap</td><td style="text-align:left;">Brotli compression level capped at 6 instead of 11.</td><td style="text-align:left;"><code>src/compression/codecs.ts</code></td><td style="text-align:left;">Balances CPU consumption against byte savings during high-throughput edge proxying.</td></tr></tbody></table>',3)])])}const y=e(s,[["render",n]]);export{m as __pageData,y as default};
